import {
 parse4WallAreas,
} from "../parsers/parse4WallAreas.js";
import {
 parse4WallScans,
} from "../parsers/parse4WallScans.js";
import {
 parseQad32,
} from "../parsers/parseQad32.js";
import {
 parseISPBB,
} from "../parsers/parseISPBB.js";
import {
 parseBom,
} from "../parsers/parseBom.js";
import {
 parseCostPart,
} from "../parsers/parseCostPart.js";
import {
 explodeBom,
} from "./explodeBom.js";
import {
 reconcileInventory,
 calculateFinancialSummary,
} from "./reconcileInventory.js";

/**
* MOTOR PRINCIPAL DEL INVENTARIO
*
* Recibe las filas ya leídas de:
*
* - 4Wall Areas
* - 4Wall Scans
* - QAD 3.2
* - ISPBB
* - BOM
* - Cost Part
*
* Y regresa:
*
* - parsers normalizados
* - explosión Phantom
* - conciliación completa
* - KPIs financieros
* - diagnósticos
*/
export function buildInventoryEngine({
 areaRows = [],
 scanRows = [],
 qadRows = [],
 ispbbRows = [],
 bomRows = [],
 costRows = [],
 options = {},
}) {
 const {
   site = "179A",
   criticalUsdThreshold = 10000,
   filterQadItemTypes = true,
 } = options;

 // ==================================================
 // 1. DICCIONARIO DE ÁREAS 4WALL
 // ==================================================
 const areas =
   parse4WallAreas(
     areaRows
   );

 // ==================================================
 // 2. FÍSICO 4WALL
 // ==================================================
 const physical =
   parse4WallScans(
     scanRows,
     areas
   );

 // ==================================================
 // 3. QAD 3.2 CONGELADO
 // ==================================================
 const qad =
   parseQad32(
     qadRows,
     {
       site,
       filterItemTypes:
         filterQadItemTypes,
     }
   );

 // ==================================================
 // 4. ISPBB / PHANTOMS
 // ==================================================
 const planning =
   parseISPBB(
     ispbbRows,
     {
       site,
     }
   );

 // ==================================================
 // 5. BOM
 // ==================================================
 const bom =
   parseBom(
     bomRows
   );

 // ==================================================
 // 6. COST PART
 // ==================================================
 const costs =
   parseCostPart(
     costRows
   );

 // ==================================================
 // 7. EXPLOSIÓN DE PHANTOMS
 // ==================================================
 const phantomAdjustments =
   explodeBom({
     physical,
     bom,
     planning,
   });

 // ==================================================
 // 8. RECONCILIACIÓN
 // ==================================================
 const reconciliation =
   reconcileInventory({
     physical,
     qad,
     planning,
     costs,
     bom,
     phantomAdjustments,
   });

 // ==================================================
 // 9. RESUMEN FINANCIERO
 // ==================================================
 const summary =
   calculateFinancialSummary(
     reconciliation,
     {
       criticalUsdThreshold,
     }
   );

 // ==================================================
 // 10. DIAGNÓSTICOS
 // ==================================================
 const diagnostics =
   buildDiagnostics({
     areas,
     physical,
     qad,
     planning,
     bom,
     costs,
     phantomAdjustments,
     reconciliation,
   });

 return {
   reconciliation,
   summary,
   diagnostics,
   sources: {
     areas,
     physical,
     qad,
     planning,
     bom,
     costs,
     phantomAdjustments,
   },
 };
}

/**
* Diagnósticos técnicos y funcionales.
*
* Esto después alimentará una pantalla:
*
* "Estado de las fuentes"
*
* para saber si algo salió mal antes
* de confiar en los dólares.
*/
function buildDiagnostics({
 areas,
 physical,
 qad,
 planning,
 bom,
 costs,
 phantomAdjustments,
 reconciliation,
}) {
 const partsWithoutCost = [];
 const partsWithoutPlanningDefinition = [];
 const unexpectedMaterial = [];
 const unmappedParts = [];
 const invMasterDifferences = [];
 let bomReviewCount = 0;

 for (
   const item
   of reconciliation
 ) {
   if (item.flags.isMissingPhysical && item.flags.hasBomReference) {
     bomReviewCount++;
   }
   // --------------------------------------
   // SIN COSTO
   // --------------------------------------
   if (
     !item.master.hasCost
   ) {
     partsWithoutCost.push(
       item.partNumber
     );
   }

   // --------------------------------------
   // SIN DEFINICIÓN PHANTOM ISPBB
   // --------------------------------------
   if (
     !item.master.phantomKnown
   ) {
     partsWithoutPlanningDefinition.push(
       item.partNumber
     );
   }

   // --------------------------------------
   // QAD = 0 Y HAY FÍSICO
   // --------------------------------------
   if (
     item.flags
       .isUnexpectedMaterial
   ) {
     unexpectedMaterial.push({
       partNumber:
         item.partNumber,
       physical:
         item.physical.total,
       netUsd:
         item.financial.netUsd,
     });
   }

   // --------------------------------------
   // ÁREA 4WALL SIN MAPEO
   // --------------------------------------
   if (
     item.flags
       .hasUnmappedPhysicalLocation
   ) {
     unmappedParts.push({
       partNumber:
         item.partNumber,
       quantity:
         item.physical
           .locations
           .get(
             "UNMAPPED"
           ) ?? 0,
       areas:
         item.physical.areas,
     });
   }

   // --------------------------------------
   // QAD DETAIL vs INV MASTER
   // --------------------------------------
   const deltaInvMaster =
     item.qad
       .detailVsInvMasterDelta;
   if (
     Math.abs(
       deltaInvMaster
     ) > 0.000001
   ) {
     invMasterDifferences.push({
       partNumber:
         item.partNumber,
       detailTotal:
         item.qad.total,
       invMasterQty:
         item.qad.invMasterQty,
       difference:
         deltaInvMaster,
     });
   }
 }

 return {
   // ======================================
   // FUENTES
   // ======================================
   sources: {
     areaCount:
       areas.totalAreas,
     mappedAreaCount:
       areas.totalMapped,
     unmappedAreaCount:
       areas.totalUnmapped,
     scanCount:
       physical.scanCount,
     physicalPartCount:
       physical.byPart.size,
     qadPartCount:
       qad.totalParts,
     ispbbPartCount:
       planning.totalParts,
     ispbbPhantomCount:
       planning.totalPhantoms,
     bomRelationCount:
       bom.totalRelations,
     bomParentCount:
       bom.totalParents,
     bomComponentCount:
       bom.totalComponents,
     costPartCount:
       costs.totalParts,
     obsoleteCatalogCount:
       costs.obsoleteParts,
     costSites:
       costs.sites,
     invalidCostCount:
       costs.invalidCostCount,
     zeroCostRows:
       costs.zeroCostRows,
     duplicateCostPartCount:
       costs.duplicatePartCount,
     conflictingCostPartCount:
       costs.conflictingDuplicatePartCount,
     invalidPhysicalQuantityCount: physical.invalidQuantityCount ?? 0,
     invalidQadQuantityCount: qad.invalidQuantityCount ?? 0,
   },

   // ======================================
   // ALERTAS
   // ======================================
   warnings: {
     missingBoms: phantomAdjustments.missingBoms,
     emptyBoms: phantomAdjustments.emptyBoms,
     unmappedAreaNames:
       physical
         .unmappedAreaNames,
     invalidPhysicalQuantityRows: physical.invalidQuantityRows ?? [],
     invalidQadQuantityRows: qad.invalidQuantityRows ?? [],
     partsWithoutCost,
     invalidCostRows:
       costs.invalidCostRows,
     duplicateCostParts:
       costs.duplicateParts,
     partsWithoutPlanningDefinition,
     unexpectedMaterial,
     unmappedParts,
     invMasterDifferences,
     phantomDefinitionMismatches:
       phantomAdjustments
         .phantomDefinitionMismatches,
   },

   // ======================================
   // PHANTOMS
   // ======================================
   phantom: {
     missingBoms: phantomAdjustments.missingBoms,
     emptyBoms: phantomAdjustments.emptyBoms,
     bomReviewCount,
     scannedParentsWithBom:
       phantomAdjustments
         .scannedParentsWithBom,
     adjustedParts:
       phantomAdjustments
         .totalAdjustedParts,
     relationsProcessed:
       phantomAdjustments
         .totalRelationsProcessed,
     contributedPieces:
       phantomAdjustments
         .totalContributedPieces,
   },
 };
}

// src/domain/normalize.js
/**
* Convierte cualquier valor a texto limpio y en mayúsculas.
*
* Ejemplos:
* " zwip "  -> "ZWIP"
* null      -> ""
* undefined -> ""
*/
export function normalizeText(value) {
 if (value === null || value === undefined) {
   return "";
 }
 return String(value)
   .trim()
   .toUpperCase();
}

/**
* Normaliza números de parte provenientes de QAD o 4Wall.
*
* IMPORTANTE:
* No quitamos guiones ni otros caracteres porque forman
* parte real del Part Number.
*/
export function normalizePartNumber(value) {
 return normalizeText(value);
}

/**
* Normaliza el Site.
*
* Ejemplo:
* 179a -> 179A
*/
export function normalizeSite(value) {
 return normalizeText(value);
}

/**
* Normaliza localidades QAD.
*
* Regla confirmada:
* En 4Wall el diccionario puede traer WHSE,
* mientras QAD utiliza ZWHSE.
*
* NO intentamos adivinar ninguna otra localidad.
*/
export function normalizeQadLocation(value) {
 const location = normalizeText(value);
 if (!location) {
   return "";
 }
 if (location === "WHSE") {
   return "ZWHSE";
 }
 return location;
}

/**
* Convierte valores provenientes de Excel/CSV/QAD a Number.
*
* Soporta:
* "1,430.0"       -> 1430
* "$37.122468"    -> 37.122468
* "(125.50)"      -> -125.50
* ""              -> 0
* null            -> 0
*/
export function toNumber(value) {
 if (value === null || value === undefined || value === "") {
   return 0;
 }
 if (typeof value === "number") {
   return Number.isFinite(value) ? value : 0;
 }
 let text = String(value).trim();
 if (!text) {
   return 0;
 }
 const isNegativeParentheses =
   text.startsWith("(") &&
   text.endsWith(")");
 text = text
   .replace(/,/g, "")
   .replace(/\$/g, "")
   .replace(/%/g, "")
   .replace(/\(/g, "")
   .replace(/\)/g, "")
   .trim();
 const number = Number(text);
 if (!Number.isFinite(number)) {
   return 0;
 }
 return isNegativeParentheses
   ? -Math.abs(number)
   : number;
}

/**
* Convierte campos Yes / No provenientes de QAD.
*
* Ejemplos:
* Yes -> true
* YES -> true
* Y   -> true
* 1   -> true
*
* No  -> false
*/
export function toBoolean(value) {
 if (typeof value === "boolean") {
   return value;
 }
 const text = normalizeText(value);
 return [
   "YES",
   "Y",
   "TRUE",
   "1",
   "SI",
   "SÍ"
 ].includes(text);
}

/**
* Normaliza Status provenientes de QAD.
*
* Ejemplos:
* "obsolete " -> "OBSOLETE"
* "discont"    -> "DISCONT"
*/
export function normalizeStatus(value) {
 return normalizeText(value);
}

/**
* Nos permite identificar explícitamente
* ganancias de material OBSOLETE.
*
* Esta función NO decide el impacto financiero.
* Solo responde si el status es OBSOLETE.
*/
export function isObsoleteStatus(value) {
 return normalizeStatus(value) === "OBSOLETE";
}

/**
* Evita divisiones, cálculos o visualizaciones
* con valores NaN / Infinity.
*/
export function safeNumber(value, fallback = 0) {
 const number = Number(value);
 return Number.isFinite(number)
   ? number
   : fallback;
}

export const READ_NEWS_KEY="visteon.inventory.readNews.v1";
export function syncOperationalAlerts(previous={},findings=[],now=new Date().toISOString(),valid=false){if(!valid)return {state:previous,active:Object.values(previous).filter(x=>x.active),newIds:[],resolvedIds:[]};const next={...previous},current=new Set(findings.map(f=>f.id)),newIds=[],resolvedIds=[];for(const f of findings){const old=next[f.id];if(!old)newIds.push(f.id);next[f.id]=old?{...old,partNumber:f.partNumber,ruleCode:f.ruleCode,active:true,lastSeen:now}:{id:f.id,partNumber:f.partNumber,ruleCode:f.ruleCode,active:true,read:false,firstSeen:now,lastSeen:now};}for(const [id,x] of Object.entries(next))if(x.active&&!current.has(id)){next[id]={...x,active:false,resolvedAt:now};resolvedIds.push(id)}const all=Object.values(next).sort((a,b)=>String(b.lastSeen||"").localeCompare(String(a.lastSeen||"")));return {state:Object.fromEntries(all.filter(x=>x.active).concat(all.filter(x=>!x.active).slice(0,250)).map(x=>[x.id,x])),newIds,resolvedIds};}
export const enrichFindingsWithAlertState=(findings=[],state={})=>findings.map(f=>({...f,firstDetected:state[f.id]?.firstSeen||null,lastDetected:state[f.id]?.lastSeen||null}));

