      formulas.physical.substitution,
      "El NET usa físico reconocido, no el total bruto del escaneo.",
      `${qty(p.total)} piezas físicas reconocidas`,
      "Comparar este total y sus localidades contra QAD.",
      [scans, bom],
    ),
    step(
      "qad",
