  const physicalRefs =
    incoming.length || m.isPhantom ? [scans, ispbb, bom] : [scans, ispbb];
  const financialRefs = [...physicalRefs, qad, cost];
  const swingRefs = [...physicalRefs, areas, qad, cost];
  const metric = (
    id,
    label,
    value,
    explanation,
    refs,
    stepId,
    warning = "",
