// src/domain/reconcileInventory.js
import {
 normalizePartNumber,
 safeNumber,
} from "./normalize.js";

function cloneLocationMap(source) {
 const result = new Map();
 if (!(source instanceof Map)) {
   return result;
 }
 for (const [location, qty] of source.entries()) {
   result.set(location, safeNumber(qty));
 }
 return result;
}

function addToLocation(map, location, quantity) {
 const key = String(location || "UNMAPPED")
   .trim()
   .toUpperCase();
 const previous = map.get(key) ?? 0;
 map.set(
   key,
   previous + safeNumber(quantity)
 );
}

function sumLocationMap(map) {
 let total = 0;
 if (!(map instanceof Map)) {
   return total;
 }
 for (const qty of map.values()) {
   total += safeNumber(qty);
 }
 return total;
}

/**
* Calcula SWING comparando localidad contra localidad.
*
* Ejemplo:
*
* Físico:
* ZWHSE = 0
* ZWIP  = 100
*
* QAD:
* ZWHSE = 100
* ZWIP  = 0
*
* SWING = |0 - 100| + |100 - 0|
*       = 200
*
* NO se divide entre dos.
*/
function calculateSwing(
 physicalLocations,
 qadLocations
) {
 const allLocations = new Set([
   ...physicalLocations.keys(),
   ...qadLocations.keys(),
 ]);
 let swingPieces = 0;
 const detail = [];
 for (const location of allLocations) {
   const physicalQty =
     safeNumber(
       physicalLocations.get(location)
     );
   const qadQty =
     safeNumber(
       qadLocations.get(location)
     );
   const delta =
     physicalQty - qadQty;
   const absoluteDelta =
     Math.abs(delta);
   swingPieces += absoluteDelta;
   detail.push({
     location,
     physicalQty,
     qadQty,
     delta,
     swingPieces:
       absoluteDelta,
   });
 }
 return {
   swingPieces,
   detail,
 };
}

/**
* Clasificación para UI.
*
* NO modifica cálculos.
* Solo ayuda al dashboard.
*/
function getFinancialStatus({
 netUsd,
 swingUsd,
 isObsolete,
 obsoleteGainUsd,
 isUnexpectedMaterial,
 physicalTotal,
 qadTotal,
 hasCost,
 netPieces,
 swingPieces,
}) {
 if (!hasCost && (netPieces !== 0 || swingPieces > 0)) {
   return "UNVALUED";
 }
 if (
   isObsolete &&
   obsoleteGainUsd > 0
 ) {
   return "OBSOLETE_GAIN";
 }
 if (isUnexpectedMaterial) {
   return "UNEXPECTED";
 }
 if (
   physicalTotal === 0 &&
   qadTotal > 0
 ) {
   return "MISSING_PHYSICAL";
 }
 if (netUsd < 0) {
   return "LOSS";
 }
 if (netUsd > 0) {
   return "GAIN";
 }
 if (swingUsd > 0) {
   return "SWING";
 }
 return "BALANCED";
}

/**
* Une:
*
* - 4Wall físico
* - QAD 3.2 congelado
* - ISPBB / Phantom
* - Cost Part
* - Ajustes BOM
*
* Este archivo contiene las reglas financieras.
*
* React NO debe recalcular nada de esto.
*/
export function reconcileInventory({
 physical,
 qad,
 planning,
 costs,
 bom,
 phantomAdjustments,
}) {
 const physicalMap =
   physical?.byPart ?? new Map();
 const qadMap =
   qad?.byPart ?? new Map();
 const planningMap =
   planning?.byPart ?? new Map();
 const costMap =
   costs?.byPart ?? new Map();
 const bomByComponent =
   bom?.byComponent ?? new Map();
 const phantomMap =
   phantomAdjustments?.byPart ??
   phantomAdjustments ??
   new Map();

 /**
  * Una pieza aparece en reconciliación
  * si existe:
  *
  * - físicamente
  * - en QAD
  * - o fue generada por explosión BOM
  *
  * No metemos las 95k piezas de Cost Part
  * solamente porque existan en el catálogo.
  */
 const allPartNumbers =
   new Set([
     ...physicalMap.keys(),
     ...qadMap.keys(),
     ...phantomMap.keys(),
   ]);

 const result = [];

 for (
   const rawPartNumber
   of allPartNumbers
 ) {
   const partNumber =
     normalizePartNumber(
       rawPartNumber
     );
   if (!partNumber) {
     continue;
   }

   const physicalItem =
     physicalMap.get(partNumber);
   const qadItem =
     qadMap.get(partNumber);
   const planningItem =
     planningMap.get(partNumber);
   const costItem =
     costMap.get(partNumber);
   const phantomAdjustment =
     phantomMap.get(partNumber);
   const bomReferences =
     bomByComponent.get(partNumber) ?? [];

   // ---------------------------------
   // 1. FÍSICO DIRECTO 4WALL
   // ---------------------------------
   const directPhysicalLocations =
     cloneLocationMap(
       physicalItem?.locations
     );
   const physicalDirectTotal =
     physicalItem
       ? safeNumber(
           physicalItem.physicalTotal
         )
       : sumLocationMap(
           directPhysicalLocations
         );

   // ---------------------------------
   // 2. AJUSTE BOM / PHANTOM
   // ---------------------------------
   const physicalLocations = planningItem?.phantom === true
     ? new Map()
     : cloneLocationMap(directPhysicalLocations);
   const bomContribution =
     safeNumber(
       phantomAdjustment
         ?.totalContribution ??
       phantomAdjustment
         ?.quantity ??
       0
     );

   /**
    * Por defecto una contribución BOM
    * representa material en proceso.
    *
    * El archivo explodeBom.js que haremos
    * después podrá entregar byLocation
    * explícitamente.
    */
   if (
     phantomAdjustment
       ?.byLocation instanceof Map
   ) {
     for (
       const [
         location,
         quantity
       ]
       of phantomAdjustment
         .byLocation
         .entries()
     ) {
       addToLocation(
         physicalLocations,
         location,
         quantity
       );
     }
   } else if (
     bomContribution !== 0
   ) {
     addToLocation(
       physicalLocations,
       "ZWIP",
       bomContribution
     );
   }

   const physicalTotal =
     sumLocationMap(
       physicalLocations
     );

   // ---------------------------------
   // 3. QAD CONGELADO 3.2
   // ---------------------------------
   const qadLocations =
     cloneLocationMap(
       qadItem?.locations
     );
   const qadTotal =
     qadItem
       ? safeNumber(
           qadItem.qadTotal
         )
       : sumLocationMap(
           qadLocations
         );

   // ---------------------------------
   // 4. COSTO FINANCIERO
   // ---------------------------------
   const hasCost =
     costItem?.hasValidCost === true;
   const costState = costItem ? (costItem.costConflict ? "CONFLICT" : costItem.hasValidCost ? "VALID" : "INVALID") : "MISSING";
   const unitCost =
     hasCost
       ? safeNumber(costItem.costTotal)
       : 0;

   // ---------------------------------
   // 5. NET
   // ---------------------------------
   const netPieces =
     physicalTotal -
     qadTotal;
   const netUsd =
     netPieces *
     unitCost;

   /**
    * Separamos pérdidas y ganancias
    * para las juntas de Finanzas.
    *
    * loss queda negativa.
    * gain queda positiva.
    */
   const grossLossUsd =
     netUsd < 0
       ? netUsd
       : 0;
   const grossGainUsd =
     netUsd > 0
       ? netUsd
       : 0;

   // ---------------------------------
   // 6. SWING
   // ---------------------------------
   const swing =
     calculateSwing(
       physicalLocations,
       qadLocations
     );
   const swingPieces =
     swing.swingPieces;
   const swingUsd =
     swingPieces *
     unitCost;

   // ---------------------------------
   // 7. PHANTOM
   // ---------------------------------
   /**
    * La única fuente autoritativa
    * para Phantom es ISPBB.
    */
   const phantomKnown =
     Boolean(planningItem);
   const isPhantom =
     planningItem
       ?.phantom === true;

   // ---------------------------------
   // 8. OBSOLETO
   // ---------------------------------
   /**
    * Status financiero viene
    * de Cost Part Browse.
    */
   const isObsolete =
     costItem
       ?.isObsolete === true;
   /**
    * Solo se aísla cuando:
    *
    * OBSOLETE
    * y
    * físico > QAD
    */
   const obsoleteGainUsd =
     isObsolete &&
     netUsd > 0
       ? netUsd
       : 0;

   // ---------------------------------
   // 9. EXCEPCIONES
   // ---------------------------------
   const isUnexpectedMaterial =
     qadTotal === 0 &&
     physicalTotal > 0;
   const isMissingPhysical =
     physicalTotal === 0 &&
     qadTotal > 0;
   const hasUnmappedPhysicalLocation =
     physicalLocations.has(
       "UNMAPPED"
     );
   const hasInvalidQadLocation = qadLocations.has("NO_LOCATION");

   // ---------------------------------
   // 10. ESTADO PARA UI
   // ---------------------------------
   const financialStatus =
     getFinancialStatus({
       netUsd,
       swingUsd,
       isObsolete,
       obsoleteGainUsd,
       isUnexpectedMaterial,
       physicalTotal,
       qadTotal,
       hasCost,
       netPieces,
       swingPieces,
     });

   result.push({
     partNumber,

     // ==============================
     // FÍSICO
     // ==============================
     physical: {
       scannedTotal: physicalDirectTotal,
       directTotal: planningItem?.phantom === true ? 0 : physicalDirectTotal,
       bomContribution,
       total:
         physicalTotal,
       locations:
         physicalLocations,
       directLocations:
         directPhysicalLocations,
       scanCount:
         physicalItem
           ?.scanCount ?? 0,
       areas:
         physicalItem
           ?.areas
         ? Array.from(
             physicalItem.areas
           )
         : [],
     },

     // ==============================
     // QAD
     // ==============================
     qad: {
       total:
         qadTotal,
       locations:
         qadLocations,
       invMasterQty:
         safeNumber(
           qadItem
             ?.invMasterQty
         ),
       detailVsInvMasterDelta:
         safeNumber(
           qadItem
             ?.detailVsInvMasterDelta
         ),
       itemType:
         qadItem
           ?.itemType ?? "",
       status:
         qadItem
           ?.status ?? "",
     },

     // ==============================
     // MAESTROS
     // ==============================
     master: {
       unitCost,
       hasCost,
       costStatus:
         costItem
           ?.status ?? "",
       planningStatus:
         planningItem
           ?.status ?? "",
       description:
         costItem
           ?.description ??
         planningItem
           ?.description ??
         "",
       unitOfMeasure:
         costItem?.unitOfMeasure ?? "",
       isObsolete,
       phantomKnown,
       isPhantom,
       costState,
     },

     // ==============================
     // FINANZAS
     // ==============================
     financial: {
       netPieces,
       netUsd,
       grossLossUsd,
       grossGainUsd,
       swingPieces,
       swingUsd,
       obsoleteGainUsd,
     },

     // ==============================
     // ALERTAS
     // ==============================
     flags: {
       missingBom: (phantomAdjustments?.missingBoms ?? []).some(x => x.parentPart === partNumber),
       emptyBom: (phantomAdjustments?.emptyBoms ?? []).some(x => x.parentPart === partNumber),
       phantomQadBalance: isPhantom && qadTotal !== 0,
       zeroCost: hasCost && unitCost === 0,
       financialStatus,
       isUnexpectedMaterial,
       isMissingPhysical,
       isObsolete,
       isPhantom,
       phantomKnown,
       hasCost,
       hasUnmappedPhysicalLocation,
       hasInvalidQadLocation,
       qadPresent: Boolean(qadItem),
       physicalPresent: Boolean(physicalItem),
       hasBomAdjustment:
         bomContribution !== 0,
       hasBomReference:
         bomReferences.length > 0,
     },

     // ==============================
     // AUDITORÍA / TRACE
     // ==============================
     trace: {
       swingByLocation:
         swing.detail.map(row => ({...row, swingUsd: hasCost ? row.swingPieces * unitCost : null})),
       bomSources:
         phantomAdjustment
           ?.sources ?? [],
       bomReferences:
         bomReferences.map((relation) => ({
           parentPart: relation.parentPart,
           level: relation.level,
           rawLevel: relation.rawLevel,
           usage: relation.usage,
           site: relation.site,
         })),
       sourceRows:
         physicalItem
           ?.sourceRows ?? [],
     },
   });
 }

 /**
  * De entrada dejamos ordenada la tabla
  * por exposición financiera absoluta.
  *
  * $5,000 faltantes aparece antes
  * que 1,000 tornillos de $0.01.
  */
 result.sort(
   (a, b) =>
     Math.abs(
       b.financial.netUsd
     ) -
     Math.abs(
       a.financial.netUsd
     )
 );

 return result;
}

/**
* KPIs globales para la portada.
*
* Esto es lo que usaremos en las juntas
* de cada ~2 horas.
*/
export function calculateFinancialSummary(
 reconciliation = [],
 options = {}
) {
 const {
   criticalUsdThreshold = 10000,
 } = options;

 let netUsd = 0;
 let grossLossUsd = 0;
 let grossGainUsd = 0;
 let swingUsd = 0;
 let swingPieces = 0;
 let obsoleteGainUsd = 0;
 let physicalQty = 0;
 let qadQty = 0;
 let phantomCount = 0;
 let phantomAdjustedUsd = 0;
 let unexpectedCount = 0;
 let criticalCount = 0;
 let unmappedLocationCount = 0;
 let missingCostCount = 0;
 let unvaluedPartCount = 0;
 let unvaluedNetPieces = 0;
 let unvaluedSwingPieces = 0;
 let qadOnlyCount = 0;
 let qadOnlyExposureUsd = 0;
 let qadOnlyMissingCostCount = 0;
 let netUsdWithPhysicalEvidence = 0;
 let grossLossUsdWithPhysicalEvidence = 0;
 let grossGainUsdWithPhysicalEvidence = 0;
 let partsWithPhysicalEvidence = 0;

 for (
   const item
   of reconciliation
 ) {
   netUsd +=
     item.financial.netUsd;
   grossLossUsd +=
     item.financial.grossLossUsd;
   grossGainUsd +=
     item.financial.grossGainUsd;
   swingUsd +=
     item.financial.swingUsd;
   swingPieces +=
     item.financial.swingPieces;
   obsoleteGainUsd +=
     item.financial
       .obsoleteGainUsd;
   physicalQty +=
     item.physical.total;
   qadQty +=
     item.qad.total;

   if (
     item.flags.isPhantom
   ) {
     phantomCount++;
   }

   if (
     item.flags.hasBomAdjustment
   ) {
     phantomAdjustedUsd +=
       item.physical
         .bomContribution *
       item.master.unitCost;
   }

   if (
     item.flags
       .isUnexpectedMaterial
   ) {
     unexpectedCount++;
   }

   if (
     Math.abs(
       item.financial.netUsd
     ) >=
     criticalUsdThreshold
   ) {
     criticalCount++;
   }

   if (
     item.flags
       .hasUnmappedPhysicalLocation
   ) {
     unmappedLocationCount++;
   }

   if (
     !item.master.hasCost
   ) {
     missingCostCount++;
   }
   if (!item.master.hasCost && (item.financial.netPieces !== 0 || item.financial.swingPieces > 0)) {
     unvaluedPartCount++;
     unvaluedNetPieces += item.financial.netPieces;
     unvaluedSwingPieces += item.financial.swingPieces;
   }
   // Intraday visibility only: QAD-only parts may not have been audited yet.
   // Keep the existing financial calculation pending Finance's decision.
   if (item.flags.isMissingPhysical) {
     qadOnlyCount++;
     qadOnlyExposureUsd += Math.abs(item.financial.netUsd);
     if (!item.master.hasCost) qadOnlyMissingCostCount++;
   }

   // Vista operativa, NO validación de conteo:
   // tener al menos un escaneo o contribución BOM solo demuestra
   // que existe evidencia física para el PN; no que el PN ya terminó.
   const hasPhysicalEvidence =
     item.physical.scanCount > 0 ||
     item.physical.bomContribution !== 0;
   if (hasPhysicalEvidence) {
     partsWithPhysicalEvidence++;
     netUsdWithPhysicalEvidence += item.financial.netUsd;
     grossLossUsdWithPhysicalEvidence += item.financial.grossLossUsd;
     grossGainUsdWithPhysicalEvidence += item.financial.grossGainUsd;
   }
 }

 return {
   netUsd,
   grossLossUsd,
   grossGainUsd,
   swingUsd,
   swingPieces,
   obsoleteGainUsd,
   physicalQty,
   qadQty,
   phantomCount,
   phantomAdjustedUsd,
   unexpectedCount,
   criticalCount,
   unmappedLocationCount,
   missingCostCount,
   unvaluedPartCount,
   unvaluedNetPieces,
   unvaluedSwingPieces,
   qadOnlyCount,
   qadOnlyExposureUsd,
   qadOnlyMissingCostCount,
   netUsdWithPhysicalEvidence,
   grossLossUsdWithPhysicalEvidence,
   grossGainUsdWithPhysicalEvidence,
   partsWithPhysicalEvidence,
   totalParts:
     reconciliation.length,
   criticalUsdThreshold,
 };
}

const FOUR_WALL_COLUMNS = [
  "Ticket/FIFO",
  "AreaName",
  "subArea",
  "Escaneador",
  "auditor",
  "Numero de parte",
  "Número Parte QAD",
  "Quantity",
  "Costo Estándar",
  "Costo Total",
  "Responsable",
  "Área General",
  "Fecha agregado",
  "serial",
];
export function rawScanObject(row) {
  const raw = row?.raw_record && typeof row.raw_record === "object" ? row.raw_record : (row ?? {});
  const normalizedFallback = {
    "Número Parte QAD": raw["Numero Parte QAD"] ?? raw["Numero de parte"] ?? row?.numero_parte,
    Quantity: row?.cantidad,
    AreaName: row?.area_escaneo,
  };
  return Object.fromEntries(
    [...new Set([...FOUR_WALL_COLUMNS, ...Object.keys(raw)])].filter(key => !key.startsWith("__") && !["raw_record", "source_columns"].includes(key)).map((key) => [key, raw[key] ?? normalizedFallback[key] ?? ""]),
  );
}


// The evidence viewer shows only fields actually present in the loaded file/snapshot.
// Keep rawScanObject's established dashboard/export compatibility separately.
export function scanEvidenceObject(row) {
  const raw = row?.raw_record && typeof row.raw_record === "object" ? row.raw_record : (row || {});
  return Object.fromEntries(Object.entries(raw).filter(([key]) => !key.startsWith("__") && !["raw_record","source_columns"].includes(key)));
}

