// Bounded, direct evidence lookup for inline study sheets. No full-file scan.
export function buildEvidenceExcerpt(reference, limit = 3) {
  const entries = (reference.evidence || [])
    .slice(0, limit)
    .flatMap((evidence) => {
      const raw = reference.source?.rows?.[evidence.sourceIndex];
      if (!raw) return [];
      return [
        {
          row: reference.type === "scans" ? scanEvidenceObject(raw) : raw,
          sourceIndex: evidence.sourceIndex,
          origin: evidence.origin,
          evidence,
        },
      ];
    });
  const columns = [
    ...new Set(
      entries.flatMap(({ evidence }) => evidence.cells.map((c) => c.column)),
    ),
  ];
  return { entries, columns, usedColumns: new Set(columns) };
}

// One model for the existing source viewer, with or without tracer highlights.
export function buildSourcePreview(selection) {
  if (!selection) return { entries: [], columns: [], sheets: [] };
  const source = selection.source || {},
    evidence = new Map(
      (selection.evidence || []).map((row) => [row.sourceIndex, row]),
    );
  const isScan = selection.config?.type === "scans";
  const filePositions = new Map(),
    files = new Map();
  for (const file of source.files || [])
    files.set(file.fileName, files.has(file.fileName) ? null : file);
  const entries = [];
  for (const [sourceIndex, row] of (source.rows || []).entries()) {
    const fileName = row.__sourceFile || source.fileName || "";
    const fileIndex = filePositions.get(fileName) || 0;
    filePositions.set(fileName, fileIndex + 1);
    if (selection.config?.type === "bom") {
      if (
        selection.partNumber &&
        String(row["Parent Item"] || "")
          .trim()
          .toUpperCase() !== String(selection.partNumber).trim().toUpperCase()
      )
        continue;
      if (
        selection.fileName &&
        selection.fileName !== "__all" &&
        fileName !== selection.fileName
      )
        continue;
    }
    const ref = evidence.get(sourceIndex);
    const origin = ref?.origin ||
      row.__provenance ||
      files.get(fileName)?.rowOrigins?.[fileIndex] || {
        fileName:
          fileName ||
          (isScan
            ? "Copia 4Wall publicada por el bot"
            : "Fuente sin nombre de archivo"),
        sheetName: source.sheetName || "",
        rowNumber: null,
        firstColumn: 0,
      };
    entries.push({
      row: isScan ? scanEvidenceObject(row) : row,
      sourceIndex,
      origin,
      evidence: ref,
    });
  }
  const visibleColumn = (key) =>
    !key.startsWith("__") && !["raw_record", "source_columns"].includes(key);
  const keys = new Set((source.fields || []).filter(visibleColumn));
  entries.slice(0, 250).forEach(({ row }) =>
    Object.keys(row).forEach((k) => {
      if (visibleColumn(k)) keys.add(k);
    }),
  );
  const usedColumns = new Set(
    [...evidence.values()].flatMap((ref) => ref.cells.map((c) => c.column)),
  );
  usedColumns.forEach((key) => keys.add(key));
  const columns = [...keys];
  return {
    entries,
    columns,
    usedColumns,
    sheets: [
      ...new Set(entries.map((e) => e.origin.sheetName).filter(Boolean)),
    ],
  };
}

// History remains stored. Only evaluated findings belong in the current bell.
export function currentAlerts(state, findings, evaluationValid) {
  if (!evaluationValid) return [];
  return findings
    .map((f) => state[f.id] || { ...f, read: false })
    .filter((x) => x.active !== false);
}

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { fetch4WallScans } from "../services/supabase.js";
import { buildInventoryEngine } from "../domain/inventoryEngine.js";
const DEFAULT_REFRESH_MS = 3 * 60 * 1000;
export function useInventoryEngine({
  manualScans = null,
  areaRows = [],
  qadRows = [],
  ispbbRows = [],
  bomRows = [],
  costRows = [],
  refreshMs = DEFAULT_REFRESH_MS,
  criticalUsdThreshold = 10000,
  enabled = true,
} = {}) {
  const [scanRows, setScanRows] = useState([]),
    [loading, setLoading] = useState(false),
    [error, setError] = useState(null),
    [lastUpdated, setLastUpdated] = useState(null),
    [scanCount, setScanCount] = useState(0),
    [snapshotMeta, setSnapshotMeta] = useState(null);
  const abortControllerRef = useRef(null),
    requestRef = useRef(0);
  const refresh = useCallback(async () => {
    if (!enabled || manualScans) return;
    const requestId = ++requestRef.current;
    if (abortControllerRef.current) abortControllerRef.current.abort();
    const controller = new AbortController();
    abortControllerRef.current = controller;
    try {
      setLoading(true);
      setError(null);
      const result = await fetch4WallScans({ signal: controller.signal });
      if (requestId !== requestRef.current) return;
      setScanRows(result.rows);
      setScanCount(result.count);
      setLastUpdated(result.fetchedAt);
      setSnapshotMeta(result.snapshotMeta);
    } catch (err) {
      if (err?.name === "AbortError") return;
      if (requestId !== requestRef.current) return;
      console.error("Error actualizando 4Wall:", err);
      setError(
        err instanceof Error
          ? err
          : new Error("Error desconocido consultando 4Wall."),
      );
    } finally {
      if (requestId === requestRef.current && !controller.signal.aborted)
        setLoading(false);
    }
  }, [enabled, manualScans]);
  useEffect(() => {
    if (!enabled || manualScans) {
      requestRef.current++;
      abortControllerRef.current?.abort();
      setLoading(false);
      return undefined;
    }
    refresh();
    const id = window.setInterval(refresh, refreshMs);
    return () => {
      window.clearInterval(id);
      abortControllerRef.current?.abort();
    };
  }, [enabled, manualScans, refresh, refreshMs]);
  const activeRows = manualScans?.rows ?? scanRows;
  const activeMeta = useMemo(
    () =>
      manualScans
        ? {
            complete: true,
            snapshotId: `manual:${manualScans.fingerprint}`,
            consistencyToken: manualScans.fingerprint,
            source: "manual",
            fileName: manualScans.fileName,
          }
        : snapshotMeta,
    [manualScans, snapshotMeta],
  );
  const activeDate = manualScans?.loadedAt ?? lastUpdated;
  const engine = useMemo(() => {
    try {
      return buildInventoryEngine({
        areaRows,
        scanRows: activeRows,
        qadRows,
        ispbbRows,
        bomRows,
        costRows,
        options: {
          site: "179A",
          criticalUsdThreshold,
          filterQadItemTypes: true,
        },
      });
    } catch (err) {
      console.error("Error ejecutando inventoryEngine:", err);
      return {
        reconciliation: [],
        summary: {
          netUsd: 0,
          grossLossUsd: 0,
          grossGainUsd: 0,
          swingUsd: 0,
          swingPieces: 0,
          obsoleteGainUsd: 0,
          phantomCount: 0,
          criticalCount: 0,
          totalParts: 0,
        },
        diagnostics: null,
        sources: null,
      };
    }
  }, [
    areaRows,
    activeRows,
    qadRows,
    ispbbRows,
    bomRows,
    costRows,
    criticalUsdThreshold,
  ]);
  const connectionStatus = useMemo(
    () =>
      error
        ? {
            state: "ERROR",
            label: "Actualización fallida",
            detail: error.message,
          }
        : loading && !lastUpdated
          ? {
              state: "DEV_LOADING",
              label: "Leyendo snapshot 4Wall",
              detail: "Supabase · bot automático todavía no operativo",
            }
          : lastUpdated
            ? {
                state: "DEV_SNAPSHOT",
                label: "Snapshot 4Wall de desarrollo",
                detail: `${scanCount.toLocaleString()} registros · bot automático no operativo`,
              }
            : {
                state: "WAITING",
                label: "4Wall automático no operativo",
                detail: "Carga un archivo manual para trabajar con datos físicos",
              },
    [error, loading, lastUpdated, scanCount],
  );
  return {
    engine,
    reconciliation: engine.reconciliation,
    summary: engine.summary,
    diagnostics: engine.diagnostics,
    scanRows: activeRows,
    scanCount: manualScans ? activeRows.length : scanCount,
    lastUpdated: activeDate,
    snapshotMeta: activeMeta,
    loading: manualScans ? false : loading,
    error: manualScans ? null : error,
    connectionStatus: manualScans
      ? {
          state: "MANUAL",
          label: "Archivo manual 4Wall",
          detail: manualScans.fileName,
        }
      : connectionStatus,
    refresh,
  };
}

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { parseDelimitedFile } from "../parsers/parseDelimitedFile.js";
import { mergeBomLibrary } from "../domain/bomLibrary.js";
import { idbGet, idbSet } from "../services/browserStorage.js";
import { removeBomFileFromCloud, syncBomLibrary } from "../services/bomCloud.js";
import { downloadBomWorkbook } from "../services/exportBomWorkbook.js";
import { REFERENCE_REQUIRED_FIELDS } from "../domain/sourceCatalog.js";

export {
  REFERENCE_REQUIRED_FIELDS,
  REFERENCE_SOURCE_LABELS,
  REFERENCE_SOURCE_TYPES,
} from "../domain/sourceCatalog.js";

const BOM_KEY = "reference:bom-library.v1";
const empty = () => ({
  rows: [],
  fields: [],
  fileName: "",
  fingerprint: "",
  loaded: false,
  loading: false,
  error: null,
  warnings: [],
});
const initial = () =>
  Object.fromEntries(
    ["areas", "qad", "ispbb", "bom", "cost", "scans"].map((k) => [k, empty()]),
  );
async function parseReferenceFile(type, file) {
  if (type !== 'bom' || !file.name.toLowerCase().endsWith('.json')) return parseDelimitedFile(file, { requiredFields: REFERENCE_REQUIRED_FIELDS[type] });
  const value=JSON.parse(await file.text());
  if (!Array.isArray(value.rows) || value.rows.some(row => !row || typeof row !== 'object' || Array.isArray(row))) throw new Error('El respaldo BOM no tiene un formato válido.');
  const fields=[...new Set(value.rows.flatMap(row => Object.keys(row)))];
  return {rows:value.rows,fields,fileName:file.name,delimiter:'backup',errors:[],warnings:[],duplicateHeaders:[]};
}
async function fingerprint(file) {
  const bytes = await crypto.subtle.digest("SHA-256", await file.arrayBuffer());
  return [...new Uint8Array(bytes)]
    .map((b) => b.toString(16).padStart(2, "0"))
    .join("");
}
function bomSource(library) {
  return {
    ...empty(),
    loaded: Boolean(library.files?.length && library.rows?.length),
    rows: library.rows,
    files: library.files,
    fileName: library.files.length ? library.files.map((file) => file.fileName).join(", ") : "",
    fingerprint:
      library.files
        .map((f) => f.fingerprint)
        .sort()
        .join(":") || "bom-empty-v1",
    fields: Object.keys(library.rows[0] ?? {}),
    loadedAt: new Date(),
  };
}
export function useReferenceFiles() {
  const [sources, setSources] = useState(initial);
  const [cloudStatus, setCloudStatus] = useState({ state: "pending", message: "BOM guardados en esta computadora; respaldo compartido pendiente." });
  const library = useRef({ rows: [], files: [] }),
    queue = useRef(Promise.resolve()),
    mounted = useRef(false);
  const syncCloud = useCallback(() => {
    const operation = queue.current.then(async () => {
      setCloudStatus(s => ({ ...s, state: "syncing", message: "Comparando y respaldando BOM…" }));
      try {
        const local = await idbGet(BOM_KEY, { rows: [], files: [] });
        if (!local.ok) throw new Error("No se pudo abrir la copia local. Reintenta antes de respaldar.");
        const merged = await syncBomLibrary(local.value);
        const changed = bomSource(merged).fingerprint !== bomSource(library.current).fingerprint;
        const saved = changed ? await idbSet(BOM_KEY, merged) : { ok: true };
        if (!saved.ok) throw new Error("El respaldo compartido está guardado, pero no pudimos actualizar la copia local.");
        library.current = merged;
        if (mounted.current) {
          if (changed) setSources(s => ({ ...s, bom: bomSource(merged) }));
          setCloudStatus(s => ({ ...s, state: "saved", message: "BOM comparados y respaldados en Supabase." }));
        }
      } catch (error) {
        if (mounted.current) setCloudStatus(s => ({ ...s, state: "pending", message: error.message }));
      }
    });
    queue.current = operation.catch(() => {});
    return operation;
  }, []);
  useEffect(() => {
    mounted.current = true;
    queue.current = queue.current.then(async () => {
      const result = await idbGet(BOM_KEY, { rows: [], files: [] });
      if (!mounted.current) return;
      if (!result.ok) {
        setSources((s) => ({
          ...s,
          bom: {
            ...s.bom,
            error: new Error(
              "No pudimos abrir los BOM guardados. Recarga antes de agregar archivos.",
            ),
          },
        }));
        return;
      }
      library.current = result.value;
      setSources((s) => ({ ...s, bom: bomSource(result.value) }));
    });
    return () => {
      mounted.current = false;
    };
  }, []);
  useEffect(() => {
    const retry = () => { void syncCloud(); };
    queueMicrotask(retry);
    window.addEventListener("online", retry);
    const timer = window.setInterval(retry, 120000);
    return () => { window.removeEventListener("online", retry); window.clearInterval(timer); };
  }, [syncCloud]);
  const loadFile = useCallback((type, file) => {
    const operation = queue.current.then(async () => {
      if (!REFERENCE_REQUIRED_FIELDS[type] || !file)
        throw new Error("Selecciona un archivo y una fuente válida.");
      setSources((s) => ({
        ...s,
        [type]: { ...s[type], loading: true, error: null },
      }));
      try {
        const [parsed, hash] = await Promise.all([
          parseReferenceFile(type, file),
          fingerprint(file),
        ]);
        const missing = REFERENCE_REQUIRED_FIELDS[type].filter(
          (g) => !g.some((k) => parsed.fields.includes(k)),
        );
        if (missing.length)
          throw new Error(
            `Faltan columnas: ${missing.map((g) => g.join(" / ")).join(", ")}.`,
          );
        const duplicates = (parsed.duplicateHeaders ?? []).filter((k) =>
          REFERENCE_REQUIRED_FIELDS[type].flat().includes(k),
        );
        if (duplicates.length)
          throw new Error(`Columnas repetidas: ${duplicates.join(", ")}.`);
        if (parsed.errors.length)
          throw new Error(
            "No pudimos separar correctamente las columnas. Conservamos el archivo anterior.",
          );
        if (type === "scans") {
          const bad = parsed.rows.some((r) => {
            const q = String(r.Quantity ?? r.cantidad ?? "").trim();
            const pn = String(
              r["Número Parte QAD"] ??
                r["Numero Parte QAD"] ??
                r.numero_parte ??
                r["Numero de parte"] ??
                "",
            ).trim();
            return !pn || !q || !Number.isFinite(Number(q.replace(/,/g, "")));
          });
          if (bad)
            throw new Error(
              "Hay partes vacías o cantidades inválidas en los escaneos. Conservamos el reporte anterior.",
            );
        }
        if (type === "bom") {
          const invalid=parsed.rows.findIndex(r => !String(r['Parent Item']??'').trim() || !String(r.Component??'').trim() ||
            ([".2","0.2","0,2"].includes(String(r.Level??'').trim()) && String(r['Comp Phantom']??'').trim().toLowerCase()==='no' &&
              (!String(r.Usage??'').trim() || !Number.isFinite(Number(String(r.Usage).replace(/,/g,''))) || Number(String(r.Usage).replace(/,/g,''))<0)));
          if(invalid>=0) throw new Error(`Fila BOM ${invalid+2}: falta una parte o el Usage no es válido. Conservamos la colección anterior.`);
        }
        let source = {
          ...parsed,
          loaded: true,
          loading: false,
          error: null,
          fingerprint: hash,
          loadedAt: new Date(),
        };
        if (type === "bom") {
          const current = await idbGet(BOM_KEY, { rows: [], files: [] });
          if (!current.ok)
            throw new Error(
              "No pudimos abrir el respaldo BOM. No se modificó.",
            );
          const next = mergeBomLibrary(
            current.value,
            parsed.rows,
            file.name,
            hash,
          );
          const saved = await idbSet(BOM_KEY, next);
          if (!saved.ok)
            throw new Error(
              "No se pudo guardar el BOM. Conservamos la colección anterior; no cierres sin respaldar.",
            );
          library.current = next;
          source = bomSource(next);
          source.delimiter = parsed.delimiter;
          source.warnings = [
            {
              message: next.addedParents
                ? `Se agregaron ${next.addedParents} BOM nuevos.`
                : "Estos BOM ya estaban guardados. No se duplicaron.",
            },
          ];
        }
        setSources((s) => ({ ...s, [type]: source }));
        return source;
      } catch (error) {
        setSources((s) => ({
          ...s,
          [type]: { ...s[type], loading: false, error },
        }));
        throw error;
      }
    });
    queue.current = operation.catch(() => {});
    if (type === "bom") void operation.then(() => syncCloud(), () => {});
    return operation;
  }, [syncCloud]);
  const deleteBomFile = useCallback((file) => {
    const operation = queue.current.then(async () => {
      if (!file?.fingerprint) throw new Error("No se encontró la huella del BOM. No se borró nada.");
      setCloudStatus({ state: "syncing", message: `Borrando ${file.fileName || "BOM"} del respaldo compartido…` });

      const next = await removeBomFileFromCloud(file.fingerprint);
      const saved = await idbSet(BOM_KEY, next);
      if (!saved.ok) {
        throw new Error("Supabase borró el BOM, pero no pudimos actualizar la copia local. Recarga la página para sincronizar.");
      }

      library.current = next;
      if (mounted.current) {
        setSources((s) => ({ ...s, bom: bomSource(next) }));
        setCloudStatus({ state: "saved", message: `${file.fileName || "BOM"} eliminado de Supabase y de esta computadora.` });
      }
      return next;
    });

    queue.current = operation.catch((error) => {
      if (mounted.current) setCloudStatus({ state: "pending", message: error.message });
    });
    return operation;
  }, []);

  const clearFile = useCallback((type) => {
    if (type === "bom") return;
    setSources((s) => ({ ...s, [type]: empty() }));
  }, []);
  const backupBom = useCallback(
    () => downloadBomWorkbook(library.current),
    [],
  );
  const status = useMemo(() => {
    const entries = Object.entries(sources).filter(([k]) => k !== "scans");
    const required = entries.filter(([k]) => k !== "bom");
    return {
      totalSources: 5,
      loadedCount: entries.filter(([, s]) => s.loaded).length,
      loadingCount: Object.values(sources).filter((s) => s.loading).length,
      errorCount: Object.values(sources).filter((s) => s.error).length,
      hasErrors: Object.values(sources).some((s) => s.error),
      allLoaded: required.every(([, s]) => s.loaded),
      missingSources: required.filter(([, s]) => !s.loaded).map(([k]) => k),
    };
  }, [sources]);
  return {
    sources,
    status,
    areaRows: sources.areas.rows,
    qadRows: sources.qad.rows,
    ispbbRows: sources.ispbb.rows,
    bomRows: sources.bom.rows,
    costRows: sources.cost.rows,
    manualScans: sources.scans.loaded ? sources.scans : null,
    loadFile,
    deleteBomFile,
    clearFile,
    backupBom,
    cloudStatus,
    syncCloud,
  };
}

// src/parsers/parse4WallAreas.js
import {
 normalizeText,
 normalizeQadLocation,
} from "../domain/normalize.js";
export function parse4WallAreas(rows = []) {
 const byArea = new Map();
 const unmapped = [];
 const all = [];
 for (const [sourceIndex,row] of rows.entries()) {
   const id = row["Id"] ?? null;
   const areaName = normalizeText(
     row["Nombre"]
   );
   if (!areaName) {
     continue;
   }
   const rawQadLocation = normalizeText(
     row["Localidad QAD"]
   );
   const qadLocation = normalizeQadLocation(
     rawQadLocation
   );
   const item = {
     sourceIndex,
     id,
     areaName,
     description: String(
       row["Descripcion"] ?? ""
     ).trim(),
     rawQadLocation,
     qadLocation,
     responsible: String(
       row["Responsable"] ?? ""
     ).trim(),
     generalArea: normalizeText(
       row["Área General"]
     ),
     labels: String(
       row["Etiquetas"] ?? ""
     ).trim(),
     mapped: Boolean(qadLocation),
   };
   all.push(item);
   byArea.set(areaName, item);
   if (!qadLocation) {
     unmapped.push(item);
   }
 }
 return {
   byArea,
   all,
   unmapped,
   totalAreas: all.length,
   totalMapped: all.length - unmapped.length,
   totalUnmapped: unmapped.length,
 };
}

/**
* Busca una AreaName de 4Wall dentro
* del catálogo oficial.
*
* Si no existe, NO ADIVINAMOS.
*/
export function resolve4WallArea(
 areaName,
 areaCatalog
) {
 const normalizedArea = normalizeText(areaName);
 if (!normalizedArea) {
   return {
     found: false,
     areaName: "",
     qadLocation: null,
   };
 }
 const result =
   areaCatalog?.byArea?.get(normalizedArea);
 if (!result) {
   return {
     found: false,
     areaName: normalizedArea,
     qadLocation: null,
   };
 }
 return {
   found: true,
   ...result,
 };
}

import {normalizePartNumber,normalizeText,toNumber} from "../domain/normalize.js";
