// src/parsers/parseBom.js
import {
 normalizePartNumber,
 normalizeText,
 toBoolean,
 toNumber,
} from "../domain/normalize.js";

// QAD exports depths as "1", "0.2", "..3", "...4", etc.
// Unknown depths are never assumed to be direct BOM edges.
function parseBomLevel(value) {
 const raw = String(value ?? "").trim();
 const match = raw.match(/^(?:0\.|\.*)(\d+)$/);
 return match ? Number(match[1]) : null;
}

export function parseBom(rows = []) {
 const byParent = new Map();
 const byComponent = new Map();
 const relations = [];
 let ignoredRows = 0;

 for (const [sourceIndex,row] of rows.entries()) {
   const parentPart =
     normalizePartNumber(
       row["Parent Item"]
     );
   const componentPart =
     normalizePartNumber(
       row["Component"]
     );
   if (
     !parentPart ||
     !componentPart
   ) {
     ignoredRows++;
     continue;
   }
   const usage =
     toNumber(
       row["Usage"]
     );
   const relation = {
     sourceIndex,
     sequence:
       toNumber(
         row["Seq"] ??
         row["Seq  "]
       ),
     parentPart,
     parentDescription:
       String(
         row[
           "Parent Item Description"
         ] ?? ""
       ).trim(),
     parentPhantomReported:
       toBoolean(
         row["Parent Phantom"]
       ),
     sourceFile: row.__sourceFile || "",
     eligibleLevel: [".2", "0.2", "0,2"].includes(String(row["Level"] ?? "").trim()),
     level:
       parseBomLevel(row["Level"]),
     rawLevel:
       String(row["Level"] ?? "").trim(),
     componentPart,
     componentDescription:
       String(
         row[
           "Component Description"
         ] ?? ""
       ).trim(),
     usage,
     grossedUpUsage:
       toNumber(
         row["Grossed up Usage"]
       ),
     componentPhantomReported:
       (["yes", "no"].includes(String(row["Comp Phantom"] ?? "").trim().toLowerCase()) ? String(row["Comp Phantom"]).trim().toLowerCase() === "yes" : null),
     itemType:
       normalizeText(
         row["Item Type"]
       ),
     partStatus:
       normalizeText(
         row["Part Status"]
       ),
     site:
       normalizeText(
         row["Site"] ??
         row["Site "]
       ),
   };

   relations.push(relation);

   if (!byParent.has(parentPart)) {
     byParent.set(
       parentPart,
       []
     );
   }
   byParent
     .get(parentPart)
     .push(relation);

   if (
     !byComponent.has(
       componentPart
     )
   ) {
     byComponent.set(
       componentPart,
       []
     );
   }
   byComponent
     .get(componentPart)
     .push(relation);
 }

 return {
   relations,
   byParent,
   byComponent,
   totalRelations:
     relations.length,
   totalParents:
     byParent.size,
   totalComponents:
     byComponent.size,
   ignoredRows,
 };
}

import {normalizePartNumber,normalizeStatus,normalizeText,isObsoleteStatus,toNumber} from "../domain/normalize.js";
