}

import Papa from "papaparse";
function decode(buffer) {
  const bytes = new Uint8Array(buffer), utf8 = new TextDecoder("utf-8").decode(bytes);
  return utf8.includes("�") ? new TextDecoder("windows-1252").decode(bytes) : utf8;
