export function parseQad32(rows=[],options={}){
 const {site="179A",filterItemTypes=true}=options,targetSite=normalizeSite(site),byPart=new Map(),invalidQuantityRows=[];let acceptedRows=0,ignoredRows=0;
 rows.forEach((row,index)=>{
  const rowSite=normalizeSite(row["Site"]);if(targetSite&&rowSite!==targetSite){ignoredRows++;return;}
  const itemType=normalizeText(row["Item Type"]);if(filterItemTypes&&!DEFAULT_ITEM_TYPES.has(itemType)){ignoredRows++;return;}
  const partNumber=normalizePartNumber(row["Item Number"]);if(!partNumber){ignoredRows++;return;}
  const parsedQty=parseQuantity(row["Quantity On Hand"]);if(!parsedQty.valid){invalidQuantityRows.push({rowNumber:index+2,partNumber,site:rowSite,rawQuantity:parsedQty.raw});ignoredRows++;return;}
  const location=normalizeQadLocation(row["Location"])||"NO_LOCATION",quantity=parsedQty.value,invMasterQty=toNumber(row["Qty On Hand - Inv Mstr"]);
  if(!byPart.has(partNumber))byPart.set(partNumber,{partNumber,site:rowSite,itemType,status:normalizeText(row["Status"]),sourceIndices:[],locations:new Map(),qadTotal:0,qadWarehouse:0,qadWip:0,invMasterQty,inventoryStatuses:new Set()});
  const item=byPart.get(partNumber);item.sourceIndices.push(index);item.locations.set(location,(item.locations.get(location)||0)+quantity);item.qadTotal+=quantity;if(location==="ZWHSE")item.qadWarehouse+=quantity;if(location==="ZWIP")item.qadWip+=quantity;
  const inventoryStatus=normalizeText(row["Inventory Status"]);if(inventoryStatus)item.inventoryStatuses.add(inventoryStatus);if(item.invMasterQty===0&&invMasterQty!==0)item.invMasterQty=invMasterQty;acceptedRows++;
 });
 for(const item of byPart.values())item.detailVsInvMasterDelta=item.qadTotal-item.invMasterQty;
 return {byPart,acceptedRows,ignoredRows,totalParts:byPart.size,invalidQuantityRows,invalidQuantityCount:invalidQuantityRows.length};
}

import Dexie from "dexie";

// Preserve the existing database and its out-of-line keys during the upgrade.
export const browserDb = new Dexie("visteon-inventory-ui");
browserDb.version(2).stores({ state: "", alerts: "&id, inventoryId" });
export const STORAGE_WARNING =
  "No pudimos guardar los últimos cambios. Puedes seguir trabajando; descarga un respaldo antes de cerrar.";
export function safeReadJson(key, fallback) {
  try {
    const raw = localStorage.getItem(key);
    return { ok: true, value: raw ? JSON.parse(raw) : fallback };
  } catch (error) {
    return { ok: false, value: fallback, error };
  }
}
// Only small preferences remain in localStorage.
export function safeWriteJson(key, value) {
  try {
    localStorage.setItem(key, JSON.stringify(value));
    return { ok: true };
  } catch (error) {
    return { ok: false, error };
  }
}
export async function idbGet(key, fallback = null) {
  try {
    return { ok: true, value: (await browserDb.state.get(key)) ?? fallback };
  } catch (error) {
    return { ok: false, value: fallback, error };
  }
}
export async function idbSet(key, value) {
  try {
    await browserDb.state.put(value, key);
    return { ok: true };
  } catch (error) {
    return { ok: false, error };
  }
}
export async function loadAlerts(inventoryId) {
  await browserDb.transaction(
    "rw",
    browserDb.state,
    browserDb.alerts,
    async () => {
      const key = `alerts:${inventoryId}`;
      const old = await browserDb.state.get(key);
      if (old && typeof old === "object") {
        const records = Object.values(old)
          .filter((x) => x?.id)
          .map((x) => ({ ...x, inventoryId }));
        if (records.length) await browserDb.alerts.bulkPut(records);
        await browserDb.state.delete(key);
      }
    },
  );
  return Object.fromEntries(
    (
      await browserDb.alerts.where("inventoryId").equals(inventoryId).toArray()
    ).map((x) => [x.id, x]),
  );
}
export async function saveAlerts(inventoryId, state) {
  const records = Object.values(state).map((x) => ({ ...x, inventoryId }));
  await browserDb.transaction("rw", browserDb.alerts, async () => {
    const ids = new Set(records.map((x) => x.id));
    const existing = await browserDb.alerts
      .where("inventoryId")
      .equals(inventoryId)
      .primaryKeys();
    await browserDb.alerts.bulkDelete(existing.filter((id) => !ids.has(id)));
    await browserDb.alerts.bulkPut(records);
  });
}
// Archive old local history successfully before releasing its quota.
export async function archiveLegacyStorage() {
  for (const key of [
    "visteon.inventory.operationalAlerts.v1",
    ...[1, 2, 3].map((v) => `visteon.inventory.meetingCuts.v${v}`),
  ]) {
    const raw = localStorage.getItem(key);
    if (raw === null) continue;
    await browserDb.transaction("rw", browserDb.state, async () => {
      const archiveKey = `legacy:${key}`;
      if ((await browserDb.state.get(archiveKey)) === undefined)
        await browserDb.state.put(JSON.parse(raw), archiveKey);
    });
    localStorage.removeItem(key);
  }
}
export function downloadJson(name, value) {
  const url = URL.createObjectURL(
    new Blob([JSON.stringify(value, null, 2)], { type: "application/json" }),
  );
  const a = document.createElement("a");
  a.href = url;
  a.download = name;
  a.click();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}

